INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('S02', 'detailed', 'Понор II', 'Стара планина', 'Идея', 'Средна', 12, 700, 700, '', '', '', '', 'Април – Ноември', 'https://www.google.com/search?q=weather+Bov+Lakatnik', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Бов → заслон Буковец → Лакатник, с алтернативи по по-ниски горски и черни пътища при влошено време.', 'СРЕДНО — базовите данни са дадени от теб; в тази среда не мога да потвърдя контактите и GPS координатите.', '{"summary":"Железопътната връзка по Искърското дефиле е най-удобна; при кола остава удобен трансфер между Бов и Лакатник.","car":{"available":true,"text":"До Бов и Лакатник се стига по асфалт; маршрутът е удобен за комбинация паркиране в единия край и връщане с влак.","parkingNote":"Провери наличието на места около гара Бов и Лакатник, особено в почивни дни."},"public":{"steps":[{"from":"София","to":"Бов","mode":"Влак","time":"около 1–1.5 ч","note":"Удобен старт от северния край."},{"from":"Лакатник","to":"София","mode":"Влак","time":"около 1–1.5 ч","note":"Удобен финал."}]}}'::jsonb, '[{"name":"заслон Буковец","elevation":null,"beds":null,"officialPhone":null,"altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Разполагам само с дадения от теб телефон; не мога да го съпоставя с независим втори източник без допълнително търсене."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Ориентацията в Понор при мъгла може да е трудна.","Контактите за заслона не са потвърдени с независим източник в момента."],"conclusion":"Кратък и практичен преход за уикенд, особено ако искаш железопътна логистика в двата края."}'::jsonb, '[{"date":"2026-07-16","label":"Бов → заслон Буковец → Лакатник","type":"Преход","distance":"12 км","gain":"+700 м","time":"4–6 ч","stay":"Лакатник","difficulty":"Средна"}]'::jsonb, '[{"name":"Къщи за гости в Бов","location":"Бов","rating":null,"price":null,"note":"Удобно за старт на следващ ден по Искърското дефиле."},{"name":"Къщи за гости в Лакатник","location":"Лакатник","rating":null,"price":null,"note":"Удобно при късно пристигане или за ранно тръгване."}]'::jsonb, '[{"name":"Локални таксита от Своге / Бов / Лакатник","phone":null,"note":"Полезни за кратък трансфер, ако влакът не съвпада."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('S03', 'detailed', 'вр. Козница', 'Стара планина', 'Идея', 'Висока', 18, 1100, 1100, '', '', '', '', 'Май – Октомври', 'https://www.google.com/search?q=weather+Rebrovo+Opletnya', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Томпсън/Реброво → х. Лескова → Оплетня, с възможни алтернативи през по-ниски пътеки при лоша видимост или умора.', 'СРЕДНО — ползвам базовите данни, но не мога да потвърдя телефоните, капацитета и GPS на хижата без допълнителна проверка.', '{"summary":"Логистично по-сложен от Понорските маршрути; най-удобен е вариант с влак/автобус до стартовата зона и предварително планиран трансфер от финиша.","car":{"available":true,"text":"С кола достъпът до Томпсън/Реброво и Оплетня е възможен, но конкретни паркинги и GPS точки трябва да се потвърдят предварително.","parkingNote":"Най-практично е да се остави кола в единия край и да се организира връщане от другия."},"public":{"steps":[{"from":"София","to":"Реброво / Томпсън","mode":"Влак или регионален транспорт","time":"зависи от връзките","note":"Най-вероятно е нужен междинен трансфер."},{"from":"Оплетня","to":"София","mode":"Регионален транспорт / такси","time":"зависи от връзките","note":"Финалът може да изисква предварително уговаряне."}]}}'::jsonb, '[{"name":"х. Лескова","elevation":null,"beds":null,"officialPhone":"0877 770 184","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Даденият телефон е наличен от базовите данни, но не е потвърден с втори източник в тази сесия."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Дължина и денивелация: това е най-тежкият от петте маршрута по дадените базови стойности.","Теренът вероятно е подходящ за по-опитни туристи и стабилно време.","Липсва текуща независима верификация за хижа Лескова и логистиката."],"conclusion":"Това е най-натоварващият вариант и е по-подходящ за стабилно време и туристи с добър теренен опит."}'::jsonb, '[{"date":"2026-07-16","label":"Томпсън/Реброво → х. Лескова → Оплетня","type":"Преход","distance":"18 км","gain":"+1100 м","time":"7–9 ч","stay":"Оплетня","difficulty":"Висока"}]'::jsonb, '[{"name":"Къщи за гости в Своге","location":"Своге","rating":null,"price":null,"note":"Практичен базов вариант за трансфер към началото."},{"name":"Къщи за гости в района на Лакатник / Бов","location":"Искърско дефиле","rating":null,"price":null,"note":"Алтернатива за комбиниране с влак и местен транспорт."}]'::jsonb, '[{"name":"Локални таксита от Своге / района","phone":null,"note":"Вероятно най-полезни за последните километри от/до Оплетня."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('S04', 'detailed', 'Врачански', 'Стара планина', 'Идея', 'Висока', 14, 950, 950, '', '', '', '', 'Април – Ноември', 'https://www.google.com/search?q=weather+Zverino+Cherepish', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Зверино → х. Пършевица → Черепиш, с алтернативи през по-леки горски и шосейни участъци при лоша видимост или мокър скален терен.', 'СРЕДНО — базовите данни са дадени от теб; без допълнителна проверка не мога надеждно да потвърдя хижата и контактите.', '{"summary":"Лесно се комбинира с влак в района на Искърското дефиле, но изисква добра организация за началото и края.","car":{"available":true,"text":"Достъпът до Зверино и Черепиш е възможен с кола; пътната логистика е удобна, но конкретни паркинги и GPS точки не са потвърдени тук.","parkingNote":"Провери местата около манастир Черепиш и центъра на Зверино."},"public":{"steps":[{"from":"София","to":"Зверино","mode":"Влак","time":"ориентировъчно 1.5–2.5 ч","note":"Подходящ старт за маршрута."},{"from":"Черепиш","to":"София","mode":"Влак","time":"ориентировъчно 1.5–2.5 ч","note":"Удобен финал при съвпадение с разписанието."}]}}'::jsonb, '[{"name":"х. Пършевица","elevation":null,"beds":null,"officialPhone":"0878 103 870","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Разполагам само с подадения телефон; не мога да потвърдя допълнителни контакти и GPS в тази сесия."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Маршрутът е с по-сериозна денивелация и заслужава стабилно време.","Врачанският дял може да има технични или каменисти участъци.","Липсва независима верификация за х. Пършевица в момента."],"conclusion":"Силен избор за по-опитни туристи, но не е най-леката опция за уикенд без натоварена подготовка."}'::jsonb, '[{"date":"2026-07-16","label":"Зверино → х. Пършевица → Черепиш","type":"Преход","distance":"14 км","gain":"+950 м","time":"6–8 ч","stay":"Черепиш","difficulty":"Висока"}]'::jsonb, '[{"name":"Къщи за гости в Зверино","location":"Зверино","rating":null,"price":null,"note":"Удобно за ранен старт."},{"name":"Гостоприемници / къщи за гости при Черепиш","location":"Черепиш","rating":null,"price":null,"note":"Подходящо за финал или резервна нощувка."}]'::jsonb, '[{"name":"Локални таксита от Мездра / Враца / района","phone":null,"note":"Възможен вариант за кратки трансфери до началото или края."}]'::jsonb, 'https://embed.windy.com/embed.html', '')
